import http from 'node:http';import fs from 'node:fs/promises';import path from 'node:path';import crypto from 'node:crypto';import {fileURLToPath} from 'node:url';import {createRequire} from 'node:module';import {initialize,atomic,sha} from './state.mjs';import {Builds,sourceEntries,capabilities} from './builds.mjs';
const require=createRequire(import.meta.url);const {SCOPES,domain,serviceUrl}=require('../shared/license.cjs');const sourceRoot=path.resolve(fileURLToPath(new URL('..',import.meta.url)));const root=process.env.HETUN_CLOUD_STATE;if(!root||!path.isAbsolute(root)||(()=>{const relative=path.relative(sourceRoot,path.resolve(root));return !relative||(!path.isAbsolute(relative)&&relative!=='..'&&!relative.startsWith('..'+path.sep));})())throw Error('HETUN_CLOUD_STATE必须设置为源码目录外的绝对路径');const host=process.env.HETUN_CLOUD_HOST||'127.0.0.1';const port=Number(process.env.HETUN_CLOUD_PORT||8790);const origin=serviceUrl(process.env.HETUN_CLOUD_ORIGIN||'http://127.0.0.1:'+port);if(!['127.0.0.1','::1','localhost'].includes(host)&&new URL(origin).protocol!=='https:')throw Error('公网监听须配置HTTPS origin');const db=await initialize(root);const builds=new Builds(root,db);const sessions=new Map(),limits=new Map();const fail=(text,status=400)=>Object.assign(Error(text),{status});
function json(res,status,value){res.writeHead(status,{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'});res.end(JSON.stringify(value));}
async function body(req,max=256*1024,raw=false){const chunks=[];let count=0;for await(const c of req){count+=c.length;if(count>max)throw fail('上传超过大小限制',413);chunks.push(c);}const bytes=Buffer.concat(chunks);return raw?bytes:JSON.parse(bytes.toString()||'{}');}
function rate(req,type,max){const id=type+':'+req.socket.remoteAddress,now=Date.now();let r=limits.get(id);if(!r||r.at+60000<=now){r={at:now,n:0};limits.set(id,r);}if(++r.n>max)throw fail('请求过于频繁，请稍后再试',429);if(limits.size>1000)for(const [k,v]of limits)if(v.at+60000<now)limits.delete(k);}
function auth(req){const token=(req.headers.cookie||'').match(/(?:^|;\s*)hetun_cloud=([a-f0-9]+)/)?.[1],s=sessions.get(token);if(!s||s.exp<Date.now()){if(token)sessions.delete(token);throw fail('请登录云端管理后台',401);}if(!['GET','HEAD'].includes(req.method)&&(req.headers.origin!==origin||req.headers['x-hetun-csrf']!==s.csrf))throw fail('管理请求来源或CSRF校验失败',403);return s;}
function publicLicense(l){const {keyHash,...rest}=l;return rest;}
function validateLicense(input,old={}){const x={...old};x.name=String(input.name??old.name??'').trim().slice(0,80);if(!x.name)throw fail('客户名称不能为空');x.domains=(input.domains??old.domains??[]).map(domain);x.domains=[...new Set(x.domains)];if(!x.domains.length||x.domains.length>20)throw fail('授权域名须为1至20个');x.scopes=(input.scopes??old.scopes??[]).filter(s=>SCOPES.includes(s));x.scopes=[...new Set(x.scopes)];if(!x.scopes.length)throw fail('至少选择一个授权产品');x.themes=[...new Set((input.themes??old.themes??[]).map(v=>String(v).trim()))];if(x.themes.length>100||x.themes.some(v=>v!=='*'&&!/^[a-z0-9][a-z0-9-]{2,100}$/.test(v)))throw fail('主题编号无效');if(x.scopes.includes('theme')&&!x.themes.length)throw fail('主题授权须指定主题编号或*');x.expiresAt=String(input.expiresAt??old.expiresAt??'');if(!Number.isFinite(Date.parse(x.expiresAt)))throw fail('请选择授权到期时间');x.expiresAt=new Date(x.expiresAt).toISOString();x.enabled=input.enabled===undefined?(old.enabled??true):input.enabled===true;x.updatedAt=new Date().toISOString();return x;}
function customer(req,hostname,scope='packer',theme=''){rate(req,'license',180);const key=(req.headers.authorization||'').match(/^Bearer (HTN_[A-Za-z0-9_-]{32,})$/)?.[1];if(!key)throw fail('授权Key无效',403);const l=db.state.licenses.find(v=>v.keyHash===sha(key));if(!l||!l.enabled)throw fail('授权不存在或已停用',403);if(Date.parse(l.expiresAt)<=Date.now())throw fail('授权已到期',403);if(!l.domains.includes(domain(hostname)))throw fail('此域名不在授权范围',403);if(!l.scopes.includes(scope))throw fail('未授权产品：'+scope,403);if(scope==='theme'&&theme&&!l.themes.includes('*')&&!l.themes.includes(theme))throw fail('此主题未授权',403);return l;}
function getSource(id){const s=db.state.sources.find(v=>v.id===id);if(!s)throw fail('源码不存在',404);return s;}
function sourceAccess(req,id){const s=getSource(id),l=customer(req,req.headers['x-hetun-domain']);if(!s.published)throw fail('源码尚未发布',404);if(s.themeId)customer(req,req.headers['x-hetun-domain'],'theme',s.themeId);return {s,l};}
async function download(res,file,filename,expected){const bytes=await fs.readFile(file);if(expected&&sha(bytes)!==expected)throw fail('文件完整性校验失败',409);res.writeHead(200,{'Content-Type':'application/octet-stream','Content-Length':bytes.length,'Content-Disposition':"attachment; filename*=UTF-8''"+encodeURIComponent(filename),'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'});res.end(bytes);}
function jobView(j){const {owner,...rest}=j;return rest;}
const server=http.createServer(async(req,res)=>{res.setHeader('X-Frame-Options','DENY');res.setHeader('Referrer-Policy','same-origin');try{const u=new URL(req.url,origin),r=u.pathname,m=req.method;
if(r==='/v1/license/health'&&m==='GET')return json(res,200,{service:'hetun-cloud',status:'ok',protocol:1,publicKey:db.keys.publicKey});
if(r==='/v1/license/lease'&&m==='POST'){const b=await body(req);if(!SCOPES.includes(b.scope)||typeof b.nonce!=='string'||b.nonce.length>100||!b.nonce)throw fail('授权参数无效');const l=customer(req,b.domain,b.scope);const sec=Math.floor(Date.now()/1000);const payload=Buffer.from(JSON.stringify({issuer:origin,licenseId:l.id,scope:b.scope,domain:domain(b.domain),themes:b.scope==='theme'?l.themes:[],licenseExpiresAt:l.expiresAt,iat:sec,exp:Math.min(sec+300,Math.floor(Date.parse(l.expiresAt)/1000)),nonce:b.nonce}));return json(res,200,{payload:payload.toString('base64url'),signature:crypto.sign(null,payload,db.keys.privateKey).toString('base64url')});}
if(r==='/api/login'&&m==='POST'){rate(req,'login',8);if(req.headers.origin!==origin)throw fail('登录来源不匹配',403);const b=await body(req);const hash=crypto.scryptSync(String(b.password||'').slice(0,200),db.admin.salt,32);if(b.username!==db.admin.username||!crypto.timingSafeEqual(hash,Buffer.from(db.admin.hash,'hex')))throw fail('账号或密码错误',401);const token=crypto.randomBytes(32).toString('hex'),csrf=crypto.randomBytes(24).toString('hex');sessions.set(token,{csrf,exp:Date.now()+8*3600000});res.setHeader('Set-Cookie','hetun_cloud='+token+'; HttpOnly; SameSite=Strict; Path=/; Max-Age=28800'+(origin.startsWith('https:')?'; Secure':''));return json(res,200,{csrf});}
if(r.startsWith('/api/')){const session=auth(req);
if(r==='/api/session'&&m==='GET')return json(res,200,{csrf:session.csrf,username:db.admin.username});
if(r==='/api/logout'&&m==='POST'){for(const [k,v]of sessions)if(v===session)sessions.delete(k);res.setHeader('Set-Cookie','hetun_cloud=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0');return json(res,200,{ok:true});}
if(r==='/api/password'&&m==='PUT'){const b=await body(req);if(!crypto.timingSafeEqual(crypto.scryptSync(String(b.current||'').slice(0,200),db.admin.salt,32),Buffer.from(db.admin.hash,'hex')))throw fail('原密码错误',403);if(typeof b.password!=='string'||b.password.length<12||b.password.length>200)throw fail('密码需要12至200个字符');db.admin.salt=crypto.randomBytes(16).toString('hex');db.admin.hash=crypto.scryptSync(b.password,db.admin.salt,32).toString('hex');await atomic(path.join(root,'admin.json'),db.admin);sessions.clear();await fs.rm(path.join(root,'bootstrap-admin.txt'),{force:true});return json(res,200,{ok:true});}
if(r==='/api/overview'&&m==='GET')return json(res,200,{sources:db.state.sources,licenses:db.state.licenses.map(publicLicense),jobs:db.state.jobs.slice(0,100).map(jobView),audit:db.state.audit.slice(0,50),workers:capabilities(),publicKey:db.keys.publicKey,origin});
if(r==='/api/licenses'&&m==='POST'){const b=await body(req),key='HTN_'+crypto.randomBytes(32).toString('base64url');const l={...validateLicense(b),id:crypto.randomUUID(),keyHash:sha(key),createdAt:new Date().toISOString()};db.state.licenses.unshift(l);db.audit('新建授权',l.id);await db.commit();return json(res,201,{license:publicLicense(l),key});}
const lr=r.match(/^\/api\/licenses\/([a-f0-9-]{36})(\/rotate)?$/);if(lr){const i=db.state.licenses.findIndex(v=>v.id===lr[1]);if(i<0)throw fail('授权不存在',404);if(m==='PATCH'&&!lr[2]){db.state.licenses[i]=validateLicense(await body(req),db.state.licenses[i]);db.audit('修改授权',lr[1]);await db.commit();return json(res,200,publicLicense(db.state.licenses[i]));}if(m==='POST'&&lr[2]){const key='HTN_'+crypto.randomBytes(32).toString('base64url');db.state.licenses[i].keyHash=sha(key);db.audit('轮换授权Key',lr[1]);await db.commit();return json(res,200,{key});}}
if(r==='/api/sources'&&m==='POST'){if(req.headers['content-type']!=='application/zip')throw fail('请上传ZIP源码包');const bytes=await body(req,40*1024*1024,true);const files=sourceEntries(bytes);const name=String(u.searchParams.get('name')||'').trim().slice(0,80),version=String(u.searchParams.get('version')||'1.0.0');if(!name||!/^[0-9A-Za-z.-]{1,40}$/.test(version))throw fail('请输入源码名称和有效版本');const themeId=String(u.searchParams.get('theme')||'');if(themeId&&!/^[a-z0-9][a-z0-9-]{2,100}$/.test(themeId))throw fail('主题编号无效');const id=crypto.randomUUID(),s={id,name,version,themeId,bytes:bytes.length,sha256:sha(bytes),files:files.size,published:false,createdAt:new Date().toISOString()};await fs.writeFile(path.join(root,'uploads',id+'.zip'),bytes,{flag:'wx'});db.state.sources.unshift(s);db.audit('上传源码',id);await db.commit();return json(res,201,s);}
const sr=r.match(/^\/api\/sources\/([a-f0-9-]{36})(\/archive)?$/);if(sr){const s=getSource(sr[1]);if(m==='PATCH'&&!sr[2]){const b=await body(req);if(typeof b.published!=='boolean')throw fail('发布状态无效');s.published=b.published;db.audit(s.published?'发布源码':'下架源码',s.id);await db.commit();return json(res,200,s);}if(m==='GET'&&sr[2])return await download(res,path.join(root,'uploads',s.id+'.zip'),s.name+'-'+s.version+'.zip',s.sha256);}
if(r==='/api/jobs'&&m==='POST')return json(res,201,jobView(await builds.create(await body(req))));
const jr=r.match(/^\/api\/jobs\/([a-f0-9-]{36})(\/(?:artifact|logs|cancel))?$/);if(jr){const j=db.state.jobs.find(v=>v.id===jr[1]);if(!j)throw fail('任务不存在',404);if(jr[2]==='/cancel'&&m==='POST')return json(res,200,jobView(await builds.cancel(j.id)));if(jr[2]==='/logs'&&m==='GET'){let text='';try{text=await fs.readFile(path.join(root,'logs',j.id+'.log'),'utf8');}catch(e){if(e.code!=='ENOENT')throw e;}return json(res,200,{text:text.slice(-60000)});}if(jr[2]==='/artifact'&&m==='GET'){if(j.status!=='complete')throw fail('任务尚未产生可下载文件',409);return await download(res,path.join(root,'outputs',j.artifact),j.name+'-'+j.target+'-'+j.artifact,j.sha256);}if(!jr[2]&&m==='GET')return json(res,200,jobView(j));}}
if(r==='/v1/catalog'&&m==='GET'){const l=customer(req,req.headers['x-hetun-domain']);return json(res,200,{sources:db.state.sources.filter(s=>s.published&&(!s.themeId||(l.scopes.includes('theme')&&(l.themes.includes('*')||l.themes.includes(s.themeId)))))});}
const cs=r.match(/^\/v1\/sources\/([a-f0-9-]{36})\/archive$/);if(cs&&m==='GET'){const {s}=sourceAccess(req,cs[1]);return await download(res,path.join(root,'uploads',s.id+'.zip'),s.name+'-'+s.version+'.zip',s.sha256);}
if(r==='/v1/jobs'){const l=customer(req,req.headers['x-hetun-domain']);if(m==='GET')return json(res,200,{jobs:db.state.jobs.filter(j=>j.owner===l.id).slice(0,50).map(jobView)});if(m==='POST'){const b=await body(req);sourceAccess(req,b.sourceId);if(!b.backend||domain(new URL(b.backend).hostname)!==domain(req.headers['x-hetun-domain']))throw fail('构建后台必须对应授权域名',403);return json(res,201,jobView(await builds.create(b,l.id)));}}
const cj=r.match(/^\/v1\/jobs\/([a-f0-9-]{36})(\/artifact)?$/);if(cj&&m==='GET'){const l=customer(req,req.headers['x-hetun-domain']),j=db.state.jobs.find(v=>v.id===cj[1]&&v.owner===l.id);if(!j)throw fail('任务不存在',404);sourceAccess(req,j.sourceId);if(!cj[2])return json(res,200,jobView(j));if(j.status!=='complete')throw fail('任务尚未完成',409);return await download(res,path.join(root,'outputs',j.artifact),j.name+'-'+j.artifact,j.sha256);}
if(m==='GET'&&['/','/app.js','/style.css'].includes(r)){const name=r==='/'?'index.html':r.slice(1);const b=await fs.readFile(path.join(sourceRoot,'public',name));res.writeHead(200,{'Content-Type':name.endsWith('.js')?'text/javascript; charset=utf-8':name.endsWith('.css')?'text/css; charset=utf-8':'text/html; charset=utf-8','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; frame-ancestors 'none'; base-uri 'none'",'Cache-Control':'no-cache'});return res.end(b);}throw fail('接口不存在',404);
}catch(e){if(!res.headersSent)json(res,e.status||400,{error:e.message});else res.end();}});
server.requestTimeout=120000;server.headersTimeout=20000;server.listen(port,host,()=>console.log('河豚云端后台：'+origin+'；运行数据在外部目录'));for(const signal of ['SIGINT','SIGTERM'])process.on(signal,()=>{builds.active?.controller.abort();server.close(()=>process.exit(0));});
